<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { Bot, Cable, CheckCircle2, Clock3, Play, PlugZap, RefreshCw, Settings2, Sparkles, Unplug, Wrench } from 'lucide-vue-next'
import { apiRequest } from '../lib/api'

interface Integration { id:string;name:string;kind:string;status:string;enabled:boolean;endpoint:string;latency_ms?:number;capabilities:string[] }
interface BotInfo { id:string;name:string;platform:string;kind:string;status:string;enabled:boolean;endpoint:string;capabilities:string[];installed:boolean;version:string;latency_ms?:number }
interface BotConfig { qq_group_id?:string|null;qq_invite_url?:string|null;reply_mode:'all'|'keywords';keywords?:string[]|string|null;intent_threshold?:number|null;pcl2_url?:string|null;modpack_url?:string|null;rules_url?:string|null;knowledge_url?:string|null;cooldown_seconds?:number|null }
interface Skill { id:string;name:string;description:string;source:string;enabled:boolean;version:string }
interface SkillJob { id:string;plugin_slug:string;plugin_name:string;repository:string;status:string;stage:string;detail:string;created_at:string;updated_at:string;skill_slug?:string;config_slug?:string }
interface ResourceSync { configured:boolean;base_url?:string|null;priority:string[];state:{auto_enabled:boolean;connected:boolean;last_scan_at?:string|null;last_error?:string|null;jobs:SkillJob[]} }
const integrations=ref<Integration[]>([]),skills=ref<Skill[]>([]),bots=ref<BotInfo[]>([]),botConfig=ref<BotConfig>({reply_mode:'all',keywords:[],intent_threshold:0.7,cooldown_seconds:10}),botKeywords=ref(''),resourceSync=ref<ResourceSync|null>(null),loading=ref(''),notice=ref('')
async function load(){const [integrationResult,syncResult,botResult]=await Promise.allSettled([apiRequest<{integrations:Integration[];skills:Skill[]}>('/api/integrations'),apiRequest<ResourceSync>('/api/resource-sync/status'),apiRequest<{bots:BotInfo[];config:BotConfig}>('/api/bots')]);if(integrationResult.status==='fulfilled'){integrations.value=integrationResult.value.integrations;skills.value=integrationResult.value.skills}else notice.value=String(integrationResult.reason);if(syncResult.status==='fulfilled')resourceSync.value=syncResult.value;if(botResult.status==='fulfilled'){bots.value=botResult.value.bots||[];botConfig.value={...botConfig.value,...botResult.value.config};botKeywords.value=Array.isArray(botConfig.value.keywords)?botConfig.value.keywords.join(', '):(botConfig.value.keywords||'')}else notice.value='机器人列表暂时无法加载：'+String(botResult.reason)}
async function toggleIntegration(item:Integration){loading.value=item.id;try{await apiRequest<Integration>('/api/integrations/'+item.id+'/toggle',{method:'POST'});await load()}finally{loading.value=''}}
async function test(item:Integration){loading.value=item.id;try{const result=await apiRequest<Integration>('/api/integrations/'+item.id+'/test',{method:'POST'});notice.value=result.name+' 连接成功，延迟 '+result.latency_ms+' ms';await load()}catch(error){notice.value=String(error)}finally{loading.value=''}}
async function toggleBot(bot:BotInfo){loading.value='bot-'+bot.id;try{await apiRequest<BotInfo>('/api/bots/'+bot.id+'/toggle',{method:'POST'});notice.value=bot.installed?'已更新 '+bot.name+' 的启用状态':'已安装并启用 '+bot.name;await load()}catch(error){notice.value='操作失败：'+String(error)}finally{loading.value=''}}
async function testBot(bot:BotInfo){loading.value='test-bot-'+bot.id;try{const result=await apiRequest<BotInfo>('/api/bots/'+bot.id+'/test',{method:'POST'});notice.value=result.name+' 测试成功'+(result.latency_ms?`，延迟 ${result.latency_ms} ms`:'');await load()}catch(error){notice.value='测试失败：'+String(error)}finally{loading.value=''}}
async function saveBotConfig(){loading.value='bot-config';try{const config={...botConfig.value,keywords:botKeywords.value.split(/[,，\n]/).map(item=>item.trim()).filter(Boolean)};botConfig.value=await apiRequest<BotConfig>('/api/bots/config',{method:'PUT',body:JSON.stringify(config)});botKeywords.value=Array.isArray(botConfig.value.keywords)?botConfig.value.keywords.join(', '):(botConfig.value.keywords||'');notice.value='机器人配置已保存'}catch(error){notice.value='配置保存失败：'+String(error)}finally{loading.value=''}}
async function toggleSkill(skill:Skill){loading.value=skill.id;try{await apiRequest<Skill>('/api/skills/'+skill.id+'/toggle',{method:'POST'});await load()}finally{loading.value=''}}
async function syncAction(action:'scan'|'run-next'){loading.value='resource-'+action;try{resourceSync.value=await apiRequest<ResourceSync>('/api/resource-sync/'+action,{method:'POST'});notice.value=action==='scan'?'主流插件 Skill 缺失扫描已完成':'已执行下一个 Skill 生成任务'}catch(error){notice.value=String(error);await load()}finally{loading.value=''}}
async function toggleAuto(){if(!resourceSync.value)return;loading.value='resource-auto';try{resourceSync.value=await apiRequest<ResourceSync>('/api/resource-sync/settings',{method:'PUT',body:JSON.stringify({auto_enabled:!resourceSync.value.state.auto_enabled})})}finally{loading.value=''}}
onMounted(load)
</script>

<template>
  <div class="integration-scroll">
    <section class="integration-hero"><div><span><PlugZap/></span><p><small>EXTENSIBILITY</small><b>Skills 与 MCP</b><em>连接 Codex、社区渠道、监控系统和专用 AI 能力。</em></p></div><i><CheckCircle2/>{{integrations.filter(item=>item.enabled).length}} 个连接已启用</i></section>
    <section class="connection-section"><header><div><small>MCP SERVERS</small><b>外部服务连接</b></div><button><Settings2/>连接配置</button></header><div class="connection-grid"><article v-for="item in integrations" :key="item.id" :class="{disabled:!item.enabled}"><header><span :class="item.status"><Cable v-if="item.enabled"/><Unplug v-else/></span><div><b>{{item.name}}</b><small>{{item.kind.toUpperCase()}} · {{item.status}}</small></div><button :class="{on:item.enabled}" @click="toggleIntegration(item)"><i/></button></header><code>{{item.endpoint}}</code><div class="chips"><i v-for="capability in item.capabilities" :key="capability">{{capability}}</i></div><footer><span><i :class="item.status"></i>{{item.enabled?(item.status==='connected'?'已连接':'已启用'):'已禁用'}}<em v-if="item.latency_ms">{{item.latency_ms}} ms</em></span><button :disabled="!item.enabled||loading===item.id" @click="test(item)"><RefreshCw :class="{spin:loading===item.id}"/>测试连接</button></footer></article></div></section>
    <section class="skill-section"><header><div><small>AGENT SKILLS</small><b>AI 能力包</b></div><span>{{skills.filter(skill=>skill.enabled).length}} / {{skills.length}} 已启用</span></header><div class="skill-grid"><article v-for="skill in skills" :key="skill.id" :class="{disabled:!skill.enabled}"><span><Bot v-if="skill.source==='builtin'"/><Sparkles v-else/></span><p><b>{{skill.name}}</b><small>{{skill.description}}</small><em>{{skill.source}} · v{{skill.version}}</em></p><button :class="{on:skill.enabled}" @click="toggleSkill(skill)"><i/></button></article></div></section>
    <section class="skill-sync-section"><header><div><small>REMOTE SKILL LIBRARY</small><b>主流插件专属 Skill 自动构建</b><em>{{resourceSync?.base_url || '未配置 SCULK_RESOURCE_API_BASE'}}</em></div><span :class="{connected:resourceSync?.state.connected}"><i/>{{resourceSync?.state.connected?'资源库已连接':resourceSync?.configured?'等待连接':'未配置'}}</span></header><div class="sync-policy"><p><b>AI 插件检索优先级</b><small>主流插件库 → 开源插件库 → 普通插件库 → 付费插件库</small></p><button :class="{on:resourceSync?.state.auto_enabled}" :disabled="!resourceSync?.configured||loading==='resource-auto'" @click="toggleAuto"><i/></button><em>{{resourceSync?.state.auto_enabled?'空闲自动生成已开启':'空闲自动生成已关闭'}}</em><button class="sync-action" :disabled="!resourceSync?.configured||!!loading" @click="syncAction('scan')"><RefreshCw :class="{spin:loading==='resource-scan'}"/>立即扫描</button><button class="sync-action primary" :disabled="!resourceSync?.configured||!!loading" @click="syncAction('run-next')"><Play/>执行下一项</button></div><p v-if="resourceSync?.state.last_error" class="sync-error">{{resourceSync.state.last_error}}</p><div class="sync-jobs"><div v-if="!resourceSync?.state.jobs.length" class="sync-empty">连接资源库后，将自动检查主流插件是否拥有专属配置 Skill。</div><article v-for="job in resourceSync?.state.jobs.slice(0,8)" :key="job.id"><span :class="job.status"><CheckCircle2 v-if="job.status==='completed'"/><Clock3 v-else/></span><p><b>{{job.plugin_name}}</b><small>{{job.detail}}</small><em>{{job.stage}} · {{new Date(job.updated_at).toLocaleString('zh-CN')}}</em></p><i>{{job.status}}</i></article></div></section>
    <section class="security-note"><Wrench/><div><b>工具权限与审批</b><small>Skills 和 MCP 只能访问显式授权的服务器与目录。停服、玩家处罚、经济修改和正式部署仍需要审批。</small></div></section>
    <div v-if="notice" class="notice">{{notice}}</div>
    <section class="bot-section"><header><div><small>BOT ADAPTERS</small><b>机器人扩展</b><em>安装并启用聊天平台适配器，让机器人接入你的社区</em></div><span>{{bots.filter(bot=>bot.enabled).length}} / {{bots.length}} 已启用</span></header><div v-if="!bots.length" class="bot-empty">暂无可用机器人扩展，稍后刷新页面重试。</div><div v-else class="bot-grid"><article v-for="bot in bots" :key="bot.id" :class="{disabled:!bot.enabled}"><header><span><Bot/></span><div><b>{{bot.name}}</b><small>{{bot.platform}} · {{bot.kind}} · v{{bot.version}}</small></div><button :class="{on:bot.enabled}" :disabled="loading==='bot-'+bot.id" @click="toggleBot(bot)"><i/></button></header><p class="bot-endpoint">{{bot.endpoint || '未提供连接地址'}}</p><div class="chips"><i v-for="capability in bot.capabilities" :key="capability">{{capability}}</i></div><footer><span><i :class="bot.status"></i>{{bot.installed?(bot.enabled?'已启用':'已安装，未启用'):'未安装'}}<em v-if="bot.latency_ms">{{bot.latency_ms}} ms</em></span><button :disabled="!bot.installed||!!loading" @click="testBot(bot)"><RefreshCw :class="{spin:loading==='test-bot-'+bot.id}"/>测试连接</button></footer></article></div><div class="bot-config"><div class="bot-config-title"><div><b>机器人配置</b><small>填写后保存，配置会应用到支持对应能力的机器人</small></div><button class="save-bot-config" :disabled="loading==='bot-config'" @click="saveBotConfig">保存配置</button></div><div class="bot-form"><label>QQ群号<input v-model="botConfig.qq_group_id" placeholder="例如 123456789" /></label><label>加群链接<input v-model="botConfig.qq_invite_url" placeholder="https://..." /></label><label>回复模式<select v-model="botConfig.reply_mode"><option value="all">回复所有消息</option><option value="keywords">仅回复关键词</option></select></label><label>意向阈值<input v-model.number="botConfig.intent_threshold" type="number" min="0" max="1" step="0.05" /></label><label class="wide">关键词<input v-model="botKeywords" placeholder="用逗号分隔，例如：服务器,整合包,联机" /></label><label>冷却时间（秒）<input v-model.number="botConfig.cooldown_seconds" type="number" min="0" step="1" /></label><label>PCL2 下载链接<input v-model="botConfig.pcl2_url" placeholder="https://..." /></label><label>Mod 整合包链接<input v-model="botConfig.modpack_url" placeholder="https://..." /></label><label>规则链接<input v-model="botConfig.rules_url" placeholder="https://..." /></label><label>知识库链接<input v-model="botConfig.knowledge_url" placeholder="https://..." /></label></div></div></section>
  </div>
</template>

